        };
        return Ok(json!({
            "command": "get",
            "status": "ok",
            "ticket": projected,
        }));
    }

    let manifest = match store.get(&id) {
        Ok(manifest) => manifest,
        Err(ticket_api::error::StorageError::NotFound(_)) => {
